{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Project-wide SSH keys are not blocked",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance does not set block-project-ssh-keys, allowing project-level SSH keys to grant access to this disaster-recovery orchestration host."
    },
    {
      "check_id": "CKV_GCP_38",
      "title": "Boot disk lacks customer-managed encryption",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The boot disk of this backup orchestration instance relies on provider-managed encryption rather than a customer-managed key, reducing control over key rotation and revocation."
    },
    {
      "check_id": "CKV_GCP_30",
      "title": "Default Compute Engine service account is used",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance explicitly uses the project's default Compute Engine service account, which may have permissions shared with unrelated workloads."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Default service account has full Cloud API scope",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The default Compute Engine service account is attached with the cloud-platform scope, exposing all permissions assigned to that shared identity to the instance."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Instance has a public IP address",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The empty access_config block assigns an external IP address, unnecessarily exposing the orchestration instance to internet-originated traffic."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Interactive serial port access is enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The serial-port-enable metadata value is explicitly true, enabling an additional administrative access path that can bypass normal network controls."
    },
    {
      "check_id": "CKV_GCP_39",
      "title": "Shielded VM protections are not enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable Secure Boot, vTPM, or integrity monitoring, weakening protection against boot-level malware and tampering."
    }
  ],
  "patched_code": "variable "orchestration_boot_disk_kms_key_self_link" {
  description = "Self-link of the customer-managed Cloud KMS key used to encrypt the orchestration instance boot disk."
  type        = string

  validation {
    condition     = length(trimspace(var.orchestration_boot_disk_kms_key_self_link)) > 0
    error_message = "A non-empty Cloud KMS key self-link must be provided."
  }
}

resource "google_service_account" "orchestration_engine" {
  account_id   = "backup-orchestration-engine"
  display_name = "Backup orchestration engine"
}

resource "google_compute_instance" "backup_orchestration_engine" {
  name         = "enterprise-disaster-recovery-orchestration-platform-compute-orchestration"
  machine_type = "e2-medium"
  zone         = "${var.primary_region}-a"

  boot_disk {
    kms_key_self_link = var.orchestration_boot_disk_kms_key_self_link

    initialize_params {
      image = "debian-cloud/debian-11"
      size  = 50
    }
  }

  network_interface {
    network    = google_compute_network.dr_vpc.id
    subnetwork = google_compute_subnetwork.management_subnet.id
  }

  service_account {
    email  = google_service_account.orchestration_engine.email
    scopes = ["cloud-platform"]
  }

  metadata = {
    block-project-ssh-keys = "true"
    serial-port-enable     = "false"
    startup-script         = file("${path.module}/scripts/orchestration-startup.sh")
  }

  shielded_instance_config {
    enable_secure_boot          = true
    enable_vtpm                 = true
    enable_integrity_monitoring = true
  }

  tags = ["dr-internal", "orchestration-engine"]

  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}
",
  "fix_summary": "Removed the public IP, disabled serial-port access, blocked project-wide SSH keys, and enabled all Shielded VM protections. The instance now uses a dedicated service account and requires a caller-supplied customer-managed KMS key for boot-disk encryption."
}
